/* Palette: #1e1e2f (bg), #2a2a40 (card), #f0f0f5 (text), #6c63ff (accent), #ffb86c (on) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1e1e2f;
  color: #f0f0f5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  color: #6c63ff;
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  color: #b0b0c0;
  margin-top: -8px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-group label {
  font-weight: 600;
  font-size: 1rem;
}

#decimal-input {
  font-size: 1.5rem;
  padding: 12px 16px;
  border-radius: 8px;
  border: 2px solid #4a4a60;
  background: #1e1e2f;
  color: #f0f0f5;
  width: 100%;
  transition: border-color 0.2s;
}

#decimal-input:focus {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.4);
}

.display-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
}

.display-item {
  flex: 1 1 140px;
  background: #1e1e2f;
  border-radius: 8px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.display-label {
  font-size: 0.875rem;
  color: #b0b0c0;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.display-value {
  font-family: 'Courier New', monospace;
  font-size: 1.5rem;
  font-weight: 700;
  color: #ffb86c;
  word-break: break-all;
}

.lamps-group {
  border: none;
  padding: 0;
}

.lamps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.lamp {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 12px 4px;
  border-radius: 12px;
  border: 2px solid #4a4a60;
  background: #1e1e2f;
  color: #b0b0c0;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.1s;
  user-select: none;
}

.lamp:hover {
  border-color: #6c63ff;
  color: #f0f0f5;
}

.lamp:focus-visible {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.4);
}

.lamp:active {
  transform: scale(0.95);
}

.lamp[aria-pressed="true"] {
  background: #ffb86c;
  border-color: #ffb86c;
  color: #1e1e2f;
}

.lamp[aria-pressed="true"]:hover {
  background: #ffc98a;
  border-color: #ffc98a;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .lamps {
    grid-template-columns: repeat(2, 1fr);
  }
  .display-value {
    font-size: 1.25rem;
  }
}

const decimalInput = document.getElementById('decimal-input');
const binaryOutput = document.getElementById('binary-output');
const hexOutput = document.getElementById('hex-output');
const lamps = document.querySelectorAll('.lamp');

let currentValue = 0;

function updateUI(value) {
  currentValue = Math.max(0, Math.min(255, value));
  decimalInput.value = currentValue;
  binaryOutput.textContent = currentValue.toString(2).padStart(8, '0');
  hexOutput.textContent = '0x' + currentValue.toString(16).toUpperCase().padStart(2, '0');
  lamps.forEach(lamp => {
    const bit = parseInt(lamp.dataset.bit, 10);
    const isOn = (currentValue >> bit) & 1;
    lamp.setAttribute('aria-pressed', isOn ? 'true' : 'false');
  });
}

decimalInput.addEventListener('input', (e) => {
  let val = parseInt(e.target.value, 10);
  if (isNaN(val)) val = 0;
  updateUI(val);
});

lamps.forEach(lamp => {
  lamp.addEventListener('click', () => {
    const bit = parseInt(lamp.dataset.bit, 10);
    const newValue = currentValue ^ (1 << bit);
    updateUI(newValue);
  });
});

// Initialize
updateUI(0);
